package com.android.tools.lint.checks;

import static com.android.SdkConstants.AUTO_URI;
import static com.android.SdkConstants.TOOLS_URI;

import com.android.annotations.NonNull;
import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

import java.util.*;

public class ConstraintLayoutDetector extends ResourceXmlDetector {
    private static final String[] CONSTRAINT_LAYOUTS = new String[] {
        "android.support.constraint.ConstraintLayout",
        "androidx.constraintlayout.widget.ConstraintLayout"
    };

    private static final String[] HORIZONTAL_CONSTRAINTS = new String[] {
        "layout_constraintStart_toStartOf",
        ...
    };
    private static final String[] VERTICAL_CONSTRAINTS = new String[] {
        ...
    };

    private static final Implementation IMPLEMENTATION = new Implementation(
        ConstraintLayoutDetector.class,
        Scope.RESOURCE_FILE_SCOPE
    );

    public static final Issue MISSING_CONSTRAINTS = Issue.create(
        "MissingConstraints",
        "Missing Constraints in ConstraintLayout",
        "The layout editor ...",
        Category.CORRECTNESS,
        6,
        Severity.WARNING,
        IMPLEMENTATION
    ).setAndroidSpecific(true);

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(CONSTRAINT_LAYOUTS);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        for (Node child = element.getFirstChild(); child != null; child = child.getNextSibling()) {
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element childElement = (Element) child;
                String tag = childElement.getTagName();
                if (tag.startsWith("android.support.constraint.") || tag.startsWith("androidx.constraintlayout.widget.")) {
                    continue;
                }
                boolean hasX = hasPositionAttribute(childElement, "layout_editor_absoluteX");
                boolean hasY = hasPositionAttribute(childElement, "layout_editor_absoluteY");
                boolean hasHorizontal = hasConstraint(childElement, HORIZONTAL_CONSTRAINTS);
                boolean hasVertical = hasConstraint(childElement, VERTICAL_CONSTRAINTS);
                if (hasX && !hasHorizontal) {
                    context.report(MISSING_CONSTRAINTS, childElement, context.getNameLocation(childElement), "This view is not constrained horizontally: only layout_editor_absoluteX was set");
                }
                if (hasY && !hasVertical) {
                    context.report(MISSING_CONSTRAINTS, childElement, context.getNameLocation(childElement), "This view is not constrained vertically: only layout_editor_absoluteY was set");
                }
            }
        }
    }

    private static boolean hasPositionAttribute(Element element, String attrName) {
        String value = element.getAttributeNS(TOOLS_URI, attrName);
        return value != null && !value.isEmpty();
    }

    private static boolean hasConstraint(Element element, String[] attrs) {
        for (String attr : attrs) {
            String value = element.getAttributeNS(AUTO_URI, attr);
            if (value != null && !value.isEmpty()) {
                return true;
            }
        }
        return false;
    }
}

